namespace HomeUtilities.ViewModels;

/// <summary>A section of the user guide that a screen's "?" button opens.</summary>
public enum HelpTopic
{
    Properties,
    Suppliers,
    Contracts,
    Meters,
    Readings,
    Categories,
    Tariffs,
    VatRates,
    Charges,
}

/// <summary>Maps a <see cref="HelpTopic"/> to the heading anchor (generated by Markdig) in each guide language.</summary>
public static class HelpTopics
{
    // Anchors follow the numbered headings of docs/user-guide/*.md; HelpContentServiceTests checks that they exist.
    private static readonly Dictionary<HelpTopic, (string En, string Ru)> Anchors = new()
    {
        [HelpTopic.Properties] = ("3-properties", "3-объекты"),
        [HelpTopic.Suppliers] = ("4-suppliers", "4-поставщики"),
        [HelpTopic.Contracts] = ("5-contracts", "5-договоры"),
        [HelpTopic.Meters] = ("6-meters", "6-счётчики"),
        [HelpTopic.Readings] = ("7-readings", "7-показания"),
        [HelpTopic.Categories] = ("8-categories", "8-категории"),
        [HelpTopic.Tariffs] = ("9-tariffs", "9-тарифы"),
        [HelpTopic.VatRates] = ("vat-rates", "ставки-ндс"),
        [HelpTopic.Charges] = ("10-charges", "10-начисления"),
    };

    public static string GetAnchor(HelpTopic topic, string language) =>
        language == HelpContentService.RussianLanguage ? Anchors[topic].Ru : Anchors[topic].En;
}
